 const q=[...ind].filter(([,n])=>n===0).map(([id])=>id),order=[];while(q.length){const n=q.shift();order.push(n);for(const x of out.get(n)||[]){ind.set(x,ind.get(x)-1);if(ind.get(x)===0)q.push(x)}}
