P.validationWouldCreateCycleV152=function(state,programmeId,from,to){if(from===to)return true;const edges=P.validationEdgesV152(state,programmeId),adj={};for(const e of edges)(adj[e.from]||(adj[e.from]=[])).push(e.to);(adj[from]||(adj[from]=[])).push(to);const seen=new Set(),stack=new Set();const dfs=n=>{if(stack.has(n))return true;if(seen.has(n))return false;seen.add(n);stack.add(n);for(const x of adj[n]||[])if(dfs(x))return true;stack.delete(n);return false};return dfs(from)};
