 const reqs=P.validationRequirementsV152(state,programmeId),nodes=P.validationNodesV152(state,programmeId),results=P.validationResultsForProgrammeV152(state,programmeId),mandatory=reqs.filter(r=>r.mandatory!==false),rows=reqs.map(r=>{const links=(r.linkedNodeIds||[]).filter(id=>nodes.some(n=>n.id===id)),rr=results.filter(x=>links.includes(x.nodeId)&&x.valid!==false),passes=rr.filter(x=>x.result==='Pass'),fails=rr.filter(x=>x.result==='Valid product failure'),status=!links.length?'Not covered':fails.length?'Failed':passes.length>=Math.max(1,Number(r.requiredQuantity||1))?'Verified':rr.length?'Partially verified':nodes.some(n=>links.includes(n.id)&&n.executionStatus==='In progress')?'In progress':'Planned';r.status=status;return {...r,linkedNodeIds:links,status}}),covered=mandatory.filter(r=>rows.find(x=>x.id===r.id)?.status!=='Not covered').length,verified=mandatory.filter(r=>rows.find(x=>x.id===r.id)?.status==='Verified').length;return {rows,total:mandatory.length,covered,verified,coveragePct:pct(covered,mandatory.length),verifiedPct:pct(verified,mandatory.length),unmapped:rows.filter(x=>x.mandatory!==false&&x.status==='Not covered'),failed:rows.filter(x=>x.status==='Failed')};
