P.validationRequirementSuggestionsV152=function(state,programmeId,requirementId){const r=P.validationRequirementsV152(state,programmeId).find(x=>x.id===requirementId);if(!r)return[];const q=`${r.category||''} ${r.verificationMethod||''} ${r.text||''}`.toLowerCase(),tests=(state.standardTests||[]).map(t=>{const terms=[t.name,t.output,t.equipmentCapability,...(t.aliases||[])].join(' ').toLowerCase();let score=0;for(const word of q.split(/\W+/).filter(x=>x.length>3))if(terms.includes(word))score++;if((/thermal|temperature/.test(q)&&/thermal|environment/.test(terms))||(/vibration/.test(q)&&/vibr/.test(terms))||(/electric|voltage|current|function/.test(q)&&/electr|function/.test(terms))||(/leak|pressure/.test(q)&&/leak|pressure/.test(terms)))score+=4;return {test:t,score}}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,4);return tests.map((x,i)=>({kind:i===0?'Existing standard test':'Possible standard/adapted test',testId:x.test.id,name:x.test.name,score:x.score,reason:`Matched requirement category/method terms to released test capability “${x.test.equipmentCapability||x.test.name}”. Engineer confirmation is required.`})).concat(tests.length?[]:[{kind:'New method development',testId:null,name:'Develop new method',score:0,reason:'No sufficiently similar controlled standard test was found. Coverage must be engineered and reviewed.'}])};

