P.validationAllocateDutsV152=function(state,programmeId,nodeId,dutIds,{reuseAllowed=false}={}){const v=P.validationDutAvailabilityV152(state,programmeId,nodeId),ids=[...new Set(dutIds||[])],bad=ids.filter(id=>!v.usable.some(d=>d.id===id));if(bad.length)return {ok:false,error:`Unavailable DUT(s): ${bad.join(', ')}`};if(!reuseAllowed){const used=new Set((state.dutAllocations||[]).filter(a=>a.programmeId===programmeId&&a.nodeId!==nodeId&&!a.reuseAllowed).flatMap(a=>a.dutIds||[]));const dup=ids.filter(id=>used.has(id));if(dup.length)return {ok:false,error:`DUT(s) already allocated exclusively: ${dup.join(', ')}`}}state.dutAllocations=(state.dutAllocations||[]).filter(a=>!(a.programmeId===programmeId&&a.nodeId===nodeId));state.dutAllocations.push({id:P.uid('VDUTALLOC'),programmeId,nodeId,dutIds:ids,reuseAllowed,updatedAt:P.now(),updatedBy:state.identity?.name||'User'});const n=P.validationNodesV152(state,programmeId).find(x=>x.id===nodeId);if(n)n.dutQuantity=ids.length;addAudit(state,'Validation DUT allocation changed','Validation Programme',programmeId,'Previous allocation',`${ids.length} DUT(s) → ${nodeId}`,reuseAllowed?'Reuse explicitly allowed':'Exclusive allocation');return {ok:true,dutIds:ids}};
