P.validationReadinessV152=function(state,programmeId){const p=P.validationProgrammeV152(state,programmeId),cov=P.validationRequirementCoverageV152(state,programmeId),nodes=P.validationNodesV152(state,programmeId),graph=P.validationGraphCheckV152(state,programmeId),checks=[];const add=(key,label,ok,resolution)=>checks.push({key,label,ok,resolution});add('spec','Controlled specification',!!p?.specification?.controlled,'Control the specification/revision.');add('coverage','Mandatory requirement coverage',cov.unmapped.length===0,'Map all mandatory requirements or add an approved deviation.');add('graph','Programme graph integrity',graph.ok,graph.issues[0]||'Reconnect the programme.');const sched=nodes.filter(n=>P.VALIDATION_NODE_TYPES_V152[n.type]?.schedulable);for(const n of sched){const f=P.validationNodeFeasibilityV152(state,programmeId,n.id);add(`node:${n.id}`,n.name||n.id,f.level!=='red',f.items.join(' · '))}return {ready:checks.every(x=>x.ok),checks,blockers:checks.filter(x=>!x.ok)}};

P.validationSpecCompareV152=function(oldReqs,newReqs){const old=new Map((oldReqs||[]).map(x=>[x.requirementId||x.id,x])),neu=new Map((newReqs||[]).map(x=>[x.requirementId||x.id,x])),added=[],removed=[],modified=[];for(const [id,n] of neu){if(!old.has(id))added.push(n);else{const o=old.get(id);if(JSON.stringify([o.text,o.acceptanceCriteria,o.verificationMethod,o.criticality])!==JSON.stringify([n.text,n.acceptanceCriteria,n.verificationMethod,n.criticality]))modified.push({id,before:o,after:n})}}for(const [id,o] of old)if(!neu.has(id))removed.push(o);return {added,removed,modified,changed:!!(added.length+removed.length+modified.length)}};

